"""Embed only source-backed UI icons in the native review app."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
assets = json.loads((root / "harmonization/asset-index.json").read_text())
icons = sorted((a for a in assets if a["category"] == "ui-used"), key=lambda a: (a["repo"].lower(), a["path"].lower()))

def rust_string(value):
    return json.dumps(value, ensure_ascii=False)

lines = [
    "//! Source-backed research icons. These are not yet canonical design-system icons.",
    "// Generated by scripts/generate_source_icons.py from harmonization/asset-index.json.",
    "pub struct SourceIcon {",
    "    pub repo: &'static str,",
    "    pub path: &'static str,",
    "    pub name: &'static str,",
    "    pub is_svg: bool,",
    "    pub bytes: &'static [u8],",
    "}",
    "pub static ALL: &[SourceIcon] = &[",
]
for asset in icons:
    path = Path("harmonization/ui-icons") / asset["repo"] / asset["path"]
    assert (root / path).is_file(), path
    include = "../../../" + path.as_posix()
    lines.append(
        "    SourceIcon { repo: %s, path: %s, name: %s, is_svg: %s, bytes: include_bytes!(%s) },"
        % (rust_string(asset["repo"]), rust_string(asset["path"]), rust_string(Path(asset["path"]).stem), str(path.suffix.lower() == ".svg").lower(), rust_string(include))
    )
lines.append("];")
(root / "src/bin/style_repo/source_icons.rs").write_text("\n".join(lines) + "\n")
print(f"Embedded {len(icons)} UI source icons")
